const modifier = (text) => {
  let modifiedText = text;
  let dayAdvanced = false; // <-- NEW: Local flag just for the Faction Mechanic

  // Initialize the counter using your preferred method
  if (!state.actionCounter) {
    state.actionCounter = 0;
  }

  // Catch actions containing ., ?, !, or the standalone word "you"
  if (text.match(/[.?!]|\byou\b/i)) {
    state.actionCounter++;
    if (state.actionCounter === 24) {
      state.message = 'Reminder: To progress, do an action with the words \'end the day\'! Optimized Context must be disabled.';
    }
    if (state.actionCounter === 75) {
      state.message = 'Reminder: To progress, do an action with the words \'end the day\'! Optimized Context must be disabled.';
    }
    if (state.actionCounter === 150) {
      state.message = 'Reminder: To progress, do an action with the words \'end the day\'! Optimized Context must be disabled. This message will stop appearing for a while.';
    }
    if (state.actionCounter === 300) {
      state.message = 'Reminder: To progress, do an action with the words \'end the day\'! Optimized Context must be disabled. This message will stop appearing for a long time.';
    }
    if (state.actionCounter === 600) {
      state.message = 'Reminder: To progress, do an action with the words \'end the day\'! Optimized Context must be disabled. That... that is quite a long day you have there.';
    }
    if (state.actionCounter === 1200) {
      state.message = 'Reminder: To progress, do an action with the words \'end the day\'! Optimized Context must be disabled. The day has STILL not ended?! Are we on Venus?';
    }
    if (state.actionCounter === 2400) {
      state.message = 'Reminder: To progress, do an action with the words \'end the day\'! Optimized Context must be disabled. Nobody will ever reach this point. #imsureofit';
    }
  }

  // --- Helper function to turn Day (1-365) into a readable Date String ---
  const getDateString = (dayNum) => {
    const months = [
      { name: "April", days: 30 }, { name: "May", days: 31 }, { name: "June", days: 30 },
      { name: "July", days: 31 }, { name: "August", days: 31 }, { name: "September", days: 30 },
      { name: "October", days: 31 }, { name: "November", days: 30 }, { name: "December", days: 31 },
      { name: "January", days: 31 }, { name: "February", days: 28 }, { name: "March", days: 31 }
    ];

    let remaining = dayNum;
    let currentMonth = "";
    let currentDate = 1;

    for (let m of months) {
      if (remaining <= m.days) {
        currentMonth = m.name;
        currentDate = remaining;
        break;
      }
      remaining -= m.days;
    }

    const daysOfWeek = ["Friday", "Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday"];
    const dow = daysOfWeek[(dayNum - 1) % 7]; 

    return `${dow}, ${currentMonth} ${currentDate}`;
  };

  // Initialize the calendar and parse cards on turn 1
  if (!state.calendarInitialized) {
    state.currentDay = 154; 
    state.calendarInitialized = true;
    state.triggerCalendarUpdate = false; // Triggers calendar generation on Turn 1

    // --- SNEAKY INJECTION: STORE & DELETE PHASE ---
    state.hiddenCards = [];
    state.hiddenWaitCards = []; 
    state.hiddenRelCards = [];

    for (let i = storyCards.length - 1; i >= 0; i--) {
      if (storyCards[i].type) {
        const typeStr = storyCards[i].type.toLowerCase();

        // 1. Detect "delayX" cards (Character)
        const delayMatch = typeStr.match(/^delay(\d*)$/);
        if (delayMatch) {
          let delayDays = delayMatch[1] ? parseInt(delayMatch[1], 10) : 1;
          state.hiddenCards.push({
            type: "character", 
            title: storyCards[i].title,
            keys: storyCards[i].keys,
            entry: storyCards[i].entry,
            description: storyCards[i].description,
            daysRemaining: delayDays 
          });
          storyCards.splice(i, 1);
          continue; 
        }

        // 2. Detect "delafX" cards (Faction)
        const delafMatch = typeStr.match(/^delaf(\d*)$/);
        if (delafMatch) {
          let delayDays = delafMatch[1] ? parseInt(delafMatch[1], 10) : 1;
          state.hiddenCards.push({
            type: "faction", 
            title: storyCards[i].title,
            keys: storyCards[i].keys,
            entry: storyCards[i].entry,
            description: storyCards[i].description,
            daysRemaining: delayDays 
          });
          storyCards.splice(i, 1);
          continue; 
        }

        // 3. Detect "waitX" cards (Character)
        const waitMatch = typeStr.match(/^wait(\d*)$/);
        if (waitMatch) {
          let waitTriggers = waitMatch[1] ? parseInt(waitMatch[1], 10) : 1;
          state.hiddenWaitCards.push({
            type: "character", 
            title: storyCards[i].title,
            keys: storyCards[i].keys,
            entry: storyCards[i].entry,
            description: storyCards[i].description,
            triggersRemaining: waitTriggers 
          });
          storyCards.splice(i, 1);
          continue;
        }

        // 4. Detect "waifX" cards (Faction)
        const waifMatch = typeStr.match(/^waif(\d*)$/);
        if (waifMatch) {
          let waifTriggers = waifMatch[1] ? parseInt(waifMatch[1], 10) : 1;
          state.hiddenWaitCards.push({
            type: "faction", 
            title: storyCards[i].title,
            keys: storyCards[i].keys,
            entry: storyCards[i].entry,
            description: storyCards[i].description,
            triggersRemaining: waifTriggers 
          });
          storyCards.splice(i, 1);
          continue;
        }
        // 5. Detect "relationship" cards
        if (typeStr === "relationship") {
          state.hiddenRelCards.push({
            type: "Relationship",
            title: storyCards[i].title,
            keys: storyCards[i].keys,
            entry: storyCards[i].entry,
            description: storyCards[i].description
          });
          storyCards.splice(i, 1);
          continue;
        }
      }
    }
  }

  // --- WAIT/WAIF TRIGGER DETECTION ---
  const waitTriggersFound = (text.match(/\b(club|committee|council|join)s?\b/gi) || []).length;  
  if (waitTriggersFound > 0 && state.hiddenWaitCards && state.hiddenWaitCards.length > 0) {
    state.hiddenWaitCards.forEach(card => {
      card.triggersRemaining -= waitTriggersFound;
    });
    state.injectWaitCards = true;
  }

  // 1. Detect the "time travel to day X" action
  const timeTravelMatch = text.match(/summon a time portal to day (\d+)/i);
  if (timeTravelMatch) {
    let targetDay = parseInt(timeTravelMatch[1], 10);
    state.currentDay = targetDay > 0 ? ((targetDay - 1) % 365) + 1 : 1;
    state.triggerCalendarUpdate = true;
    dayAdvanced = true; // <-- Flag for Factions
    modifiedText += ` 🌀 [A time portal opens... You step through and emerge on ${getDateString(state.currentDay)}]\n`;
  } 

  // 2. Detect the "autopilot" action (Skips 3 days)
  else if (text.match(/go into autopilot/i)) {
    state.currentDay += 3;
    state.currentDay = ((state.currentDay - 1) % 365) + 1; 
    state.triggerCalendarUpdate = true;
    dayAdvanced = true; // <-- Flag for Factions

    if (state.hiddenCards && state.hiddenCards.length > 0) {
      state.hiddenCards.forEach(card => card.daysRemaining -= 3);
      state.injectHiddenCards = true;
    }
    modifiedText += ` ⏩ [3 days later... Today is ${getDateString(state.currentDay)}]\n`;
  }

  // 3. Detect the "end the day" action (Skips 1 day)
  else if (text.match(/(end|pass|skip) the day/i)) {
    state.currentDay += 1;
    state.currentDay = ((state.currentDay - 1) % 365) + 1; 
    state.triggerCalendarUpdate = true;
    dayAdvanced = true; // <-- Flag for Factions

    if (state.hiddenCards && state.hiddenCards.length > 0) {
      state.hiddenCards.forEach(card => card.daysRemaining -= 1);
      state.injectHiddenCards = true; 
    }
    modifiedText += ` ☀️ [A day passed... Today is ${getDateString(state.currentDay)}]\n`;
  }

  // --- NEW: FACTION JOIN MECHANIC ---
  // Now only runs if a day-passing command was used!
  if (dayAdvanced) {
    state.actionCounter = 25
    for (let i = 0; i < storyCards.length; i++) {
      if (storyCards[i].type && storyCards[i].type.toLowerCase() === "character") {
        // Regex to capture the faction name inside the parentheses
        const joinRegex = /\(Wants to join the (.+?)\)/gi;

        // Update the card's entry text if a match is found
        if (storyCards[i].entry && joinRegex.test(storyCards[i].entry)) {
          storyCards[i].entry = storyCards[i].entry.replace(joinRegex, "($1 Member)");
        }

        // Update the card's description text if a match is found
        if (storyCards[i].description && joinRegex.test(storyCards[i].description)) {
          storyCards[i].description = storyCards[i].description.replace(joinRegex, "($1 Member)");
        }
      }
    }
  }

  // --- SNEAKY INJECTION: RESTORE PHASE ---

  // Restore Delayed Cards (Handles both delay and delaf)
  if (state.injectHiddenCards && state.hiddenCards && state.hiddenCards.length > 0) {
    const readyCards = state.hiddenCards.filter(card => card.daysRemaining <= 0);
    readyCards.forEach(cardData => {
      addStoryCard(cardData.title);
      for (let i = storyCards.length - 1; i >= 0; i--) {
        if (storyCards[i].title === cardData.title) {
          storyCards[i].type = cardData.type;
          storyCards[i].keys = cardData.keys;
          storyCards[i].entry = cardData.entry;
          storyCards[i].description = cardData.description;
          break; 
        }
      }
    });
    state.hiddenCards = state.hiddenCards.filter(card => card.daysRemaining > 0);
    delete state.injectHiddenCards; 
  }

  // Restore Wait/Waif Cards
  if (state.injectWaitCards && state.hiddenWaitCards && state.hiddenWaitCards.length > 0) {
    const readyWaitCards = state.hiddenWaitCards.filter(card => card.triggersRemaining <= 0);
    readyWaitCards.forEach(cardData => {
      addStoryCard(cardData.title);
      for (let i = storyCards.length - 1; i >= 0; i--) {
        if (storyCards[i].title === cardData.title) {
          storyCards[i].type = cardData.type;
          storyCards[i].keys = cardData.keys;
          storyCards[i].entry = cardData.entry;
          storyCards[i].description = cardData.description;
          break; 
        }
      }
    });
    state.hiddenWaitCards = state.hiddenWaitCards.filter(card => card.triggersRemaining > 0);
    delete state.injectWaitCards;
  }
// Restore Relationship Cards (Only checks after Day 154 + matches each card's own keys)
  if (state.currentDay > 154 && state.hiddenRelCards && state.hiddenRelCards.length > 0) {
    const readyRelCards = [];
    const remainingRelCards = [];

    state.hiddenRelCards.forEach(cardData => {
      // Split the card's "keys" string by comma and clean up whitespace
      const keyList = (cardData.keys || "")
        .split(",")
        .map(k => k.trim())
        .filter(k => k.length > 0);

      // Check if any of this specific card's keys appear in the player's input
      const isMatched = keyList.some(key => {
        const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const keyRegex = new RegExp(`\\b${escapedKey}\\b`, 'i');
        return keyRegex.test(text);
      });

      if (isMatched) {
        readyRelCards.push(cardData);
      } else {
        remainingRelCards.push(cardData);
      }
    });

    // Inject only the matched cards back into storyCards
    if (readyRelCards.length > 0) {
      readyRelCards.forEach(cardData => {
        addStoryCard(cardData.title);
        for (let i = storyCards.length - 1; i >= 0; i--) {
          if (storyCards[i].title === cardData.title) {
            storyCards[i].type = cardData.type;
            storyCards[i].keys = cardData.keys;
            storyCards[i].entry = cardData.entry;
            storyCards[i].description = cardData.description;
            break;
          }
        }
      });
      state.hiddenRelCards = remainingRelCards;
    }
  }
  return { text: modifiedText };
};

modifier(text);

